L.use_class("form-4","Form 4")
OUT=L.ROOT/"economics"
PATH=[]
SRC=["business"]

def F(term,meaning,case,error,why):
    return dict(term=term,meaning=meaning,case=case,error=error,why=why)

def qa(n,key,level,items):
    return B.QA(f"n4-{n}-{key}",level,"{X.q}",items,SRC)

def item(q,r,wrong,why):
    assert len(wrong)==3
    return dict(q=q,r=r,w=[x[0] for x in wrong],e=[x[1] for x in wrong],y=why)

def number(n,key,prompt,answer,vars,steps,misc,where=(),level=2,unit="CFA francs"):
    return num(f"n4-{n}-{key}",level,prompt,answer,steps,vars=vars,misc=misc,where=list(where),unit=unit,sources=SRC)

def lesson(n,title,goal,back,next_use,note,case,method,facts,applied,example=None,prereq=(),questions=None,figure=None):
    assert len(facts)==4
    defs=[]; cases=[]; reasons=[]
    for i,f in enumerate(facts):
        other=[x for j,x in enumerate(facts) if j!=i]
        defs.append(item("Which term means "+f["meaning"]+"?",f["term"],[(x["term"],x["term"]+" concerns "+x["meaning"]+", rather than the concept asked for.") for x in other],f["meaning"].capitalize()+"."))
        cases.append(item(f["case"]+"\nWhich concept best explains the highlighted feature?",f["term"],[(x["term"],"That concerns "+x["meaning"]+". This case instead concerns "+f["meaning"]+".") for x in other],f["why"]))
        reasons.append(item(f["case"]+"\nWhich explanation is appropriate?",f["why"],[(x["why"],"That explanation addresses "+x["term"]+", rather than the feature described here.") for x in other],f["meaning"].capitalize()+"."))
    q0=qa(n,"terms",1,defs); q1=qa(n,"cases",1,cases); q2=qa(n,"reasons",2,reasons)
    q4=B.SP(f"n4-{n}-repair",3,"Find the incorrect economic claim.",
        [f["term"]+": "+f["meaning"]+"." for f in facts],[(f["error"],f["why"]) for f in facts],SRC)
    for st,f in zip(q4["pool"]["right"],facts):
        st["explain"]="This is correct: "+f["meaning"]+". Look for a statement that contradicts the lesson’s distinction."
    qs=questions or [q0,q1,q2,applied,q4]
    # The case card teaches all banked cases, not an unrelated example for its random check.
    cards=[card(f"n4-{n}-c1","Distinguish these features before judging a business.",[f["term"]+": "+f["meaning"]+"." for f in facts],q0["id"]),
       card(f"n4-{n}-c2","Use the stated case evidence to identify the economic feature.",[f["case"] for f in facts],q1["id"]),
       card(f"n4-{n}-c3","Explain a consequence instead of assuming every option has the same effect.",[f["term"]+": "+f["why"] for f in facts],{**q2,"id":f"n4-{n}-reasons-card","level":1})]
    if questions:
        # Practical cards retain the concepts above, with their own consistent checks.
        cards[0]["check"]={**q0,"id":f"n4-{n}-terms-card"}
        cards[1]["check"]={**q1,"id":f"n4-{n}-cases-card"}
    sections=[("Your goal and connections","By the end, you should be able to "+goal+". Builds on: "+back+". Leads to: "+next_use+"."),
       ("Understand the economics",note),("Follow the local case",case),("Reason and check",method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson("economics","economics",n,(f"n4-{n}",title),prereq,note,
       example or worked({},facts[0]["case"]+" Explain the feature.",[facts[0]["meaning"].capitalize()+".",facts[0]["why"]],facts[0]["term"]),
       cards,qs,learn=learn(sections,key_words=[(f["term"],f["meaning"]) for f in facts],
       mistake=(facts[0]["error"],facts[0]["term"]+": "+facts[0]["meaning"]+".",facts[0]["why"])))
    PATH.append((n,title,goal,back,next_use))

profit=number(1,"profit","An invented Buea stall receives {revenue} CFA francs in sales and incurs {cost} CFA francs in the stated period. Calculate its accounting profit, ignoring taxes and other adjustments.","revenue-cost",
 {"a":{"int":[8,15]},"b":{"int":[2,6]},"revenue":{"expr":"a*1000"},"cost":{"expr":"b*1000"}},
 ["Profit is revenue minus the stated costs.","{revenue} − {cost} = {answer} CFA francs."],[("sales","revenue","Sales revenue has not yet had costs deducted."),("add","revenue+cost","Costs reduce the remainder; do not add them to revenue.")])
lesson(1,"Business units and the sole proprietor","explain sole ownership, distinguish revenue from profit and identify an ownership trade-off",
 "Form Three’s production, resources and choice","partnerships, which share ownership, resources and decisions",
 "A business unit organises resources to supply goods or services. A sole proprietorship has one owner, although it may employ workers. In the ordinary unincorporated model, the owner bears business losses and personal liability can extend beyond the funds invested. Direct control can make decisions quick, while limited finance and dependence on one person can constrain the business. Revenue is sales income; profit is revenue less the relevant costs. Neither one owner nor a small size guarantees profit.",
 "Bih owns a fictional Buea repair stall and hires an assistant. The assistant’s wage does not make the assistant a co-owner. Bih chooses services and keeps the accounting profit after costs, but also bears losses. The example illustrates ownership, not a claim that any activity may operate without local formalities.",
 "Ask who owns, who decides and who bears loss. Separate employees from owners. Calculate profit from comparable-period revenue and costs, not from money in the till alone. Do not treat the school model as a set of registration or tax instructions.",[
 F("sole ownership","ownership by one person, even when employees are hired","Bih alone owns the stall while an assistant earns a wage.","Hiring a worker automatically creates shared ownership.","A wage contract is different from owning a stake in the business."),
 F("unlimited liability","personal responsibility that can extend beyond the owner’s business investment in the ordinary model","An unpaid business debt may expose the proprietor’s personal assets.","A sole proprietor can never be exposed beyond invested cash.","The ordinary model does not separate the proprietor’s liability as a limited company does."),
 F("direct control","the owner’s ability to make decisions without co-owner approval","Bih changes the service list without consulting a partner.","Direct control guarantees that every decision is correct.","Quick decisions remain exposed to mistakes and limited expertise."),
 F("accounting profit","sales revenue less the relevant recorded costs for the period","The stall deducts its costs from its sales revenue.","All sales revenue is automatically profit.","Costs must be deducted before interpreting the remainder as profit.")],profit,
 worked({},"A fictional stall has revenue of {12000} CFA francs and costs of {8000}. Find its accounting profit.",["Use the same period and currency.","Subtract costs: {12000} − {8000} = {12000-8000}."],"{12000-8000} CFA francs."))

